class Solution {
public:
    int minimumScore(std::string s, std::string t) {
        int n = s.size(), m = t.size();
        std::vector<int> right(m, -1);
        int j = n - 1;
        for (int i = m - 1; i >= 0; --i) {
            while (j >= 0 && s[j] != t[i]) j--;
            if (j >= 0) {
                right[i] = j--;
            } else {
                break;
            }
        }
        int ans = m;
        for (int i = 0; i < m; ++i) {
            if (right[i] != -1) {
                ans = std::min(ans, i);
                break;
            }
        }
        int j_idx = 0, p = 0;
        for (int i = 0; i < m; ++i) {
            while (p < n && s[p] != t[i]) p++;
            if (p >= n) break;
            while (j_idx < m && (j_idx <= i || right[j_idx] <= p)) {
                j_idx++;
            }
            ans = std::min(ans, j_idx - i - 1);
            p++;
        }
        return ans;
    }
};

class Solution {
    public int minimumScore(String s, String t) {
        int n = s.length(), m = t.length();
        int[] right = new int[m];
        java.util.Arrays.fill(right, -1);
        int j = n - 1;
        for (int i = m - 1; i >= 0; i--) {
            while (j >= 0 && s.charAt(j) != t.charAt(i)) j--;
            if (j >= 0) {
                right[i] = j--;
            } else {
                break;
            }
        }
        int ans = m;
        for (int i = 0; i < m; i++) {
            if (right[i] != -1) {
                ans = Math.min(ans, i);
                break;
            }
        }
        int jIdx = 0, p = 0;
        for (int i = 0; i < m; i++) {
            while (p < n && s.charAt(p) != t.charAt(i)) p++;
            if (p >= n) break;
            while (jIdx < m && (jIdx <= i || right[jIdx] <= p)) {
                jIdx++;
            }
            ans = Math.min(ans, jIdx - i - 1);
            p++;
        }
        return ans;
    }
}

